   <meta name="viewport" content="width=device-width, initial-scale=1">
   <title>Support Contact Form</title>
   <style>
     :root {
       color-scheme: light;
       --bg: #f5f7fb;
       --panel: #ffffff;
       --text: #172033;
       --muted: #5e6b84;
       --border: #d8e0ee;
       --focus: #5b7cff;
       --accent: #2546d6;
       --error: #c53030;
