       margin: 0;
       min-height: 100vh;
       font-family: Inter, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
       color: var(--text);
       background:
         radial-gradient(circle at top, #e8eeff 0, transparent 35%),
         linear-gradient(180deg, #f7f9fd 0%, var(--bg) 100%);
       display: grid;
       place-items: center;
       padding: 32px 16px;
