 <body>
   <main>
     <section class="card" aria-labelledby="support-title">
       <p class="eyebrow">Support</p>
       <h1 id="support-title">Contact our support team</h1>
       <p class="subtitle">Send us your details and we’ll get back to you as soon as possible.</p>

       <form id="support-form" novalidate>
         <div class="form-grid">
           <div class="form-field" data-field="name">
             <label for="fullName">Full name<span class="required" aria-hidden="true">*</span></label>
             <input
               id="fullName"
               name="fullName"
               type="text"
               autocomplete="name"
               required
               aria-describedby="fullName-error"
               placeholder="Jane Doe"
             >
             <p class="error" id="fullName-error" aria-live="polite"></p>
           </div>

           <div class="form-field" data-field="email">
             <label for="email">Email address<span class="required" aria-hidden="true">*</span></label>
             <input
               id="email"
               name="email"
               type="email"
               autocomplete="email"
               required
               aria-describedby="email-error"
               placeholder="jane@company.com"
             >
             <p class="error" id="email-error" aria-live="polite"></p>
           </div>

           <div class="form-field" data-field="phone">
             <label for="phone">Phone number</label>
             <input
               id="phone"
               name="phone"
               type="tel"
               autocomplete="tel"
               inputmode="tel"
               aria-describedby="phone-help phone-error"
               placeholder="123-456-7890"
             >
             <p class="helper" id="phone-help">Optional. Use 123-456-7890 or +1 123 456 7890.</p>
             <p class="error" id="phone-error" aria-live="polite"></p>
           </div>
         </div>

         <div class="actions">
           <button type="submit">Send message</button>
         </div>
       </form>
     </section>
   </main>

   <script>
     const form = document.getElementById('support-form');
     const fields = {
       name: document.getElementById('fullName'),
       email: document.getElementById('email'),
       phone: document.getElementById('phone')
     };

     const errorNodes = {
       name: document.getElementById('fullName-error'),
       email: document.getElementById('email-error'),
       phone: document.getElementById('phone-error')
     };

     const fieldWraps = {
       name: fields.name.closest('.form-field'),
       email: fields.email.closest('.form-field'),
       phone: fields.phone.closest('.form-field')
     };

     const phonePattern = /^(?:\+?\d{1,3}[-.\s]?)?(?:\(?\d{3}\)?[-.\s]?)\d{3}[-.\s]?\d{4}$/;

     function setFieldState(fieldKey, message) {
       const input = fields[fieldKey];
       const error = errorNodes[fieldKey];
       const field = fieldWraps[fieldKey];
       error.textContent = message;
       field.dataset.invalid = message ? 'true' : 'false';
       input.setAttribute('aria-invalid', message ? 'true' : 'false');
     }

     function validateName() {
       const value = fields.name.value.trim();
       if (!value) {
         setFieldState('name', 'Full name is required.');
         return false;
       }
       setFieldState('name', '');
       return true;
     }

     function validateEmail() {
       const value = fields.email.value.trim();
       if (!value) {
         setFieldState('email', 'Email address is required.');
         return false;
       }
       if (!fields.email.checkValidity()) {
         setFieldState('email', 'Enter a valid email address.');
         return false;
       }
       setFieldState('email', '');
       return true;
     }

     function validatePhone() {
       const value = fields.phone.value.trim();
       if (!value) {
         setFieldState('phone', '');
         return true;
       }
       if (!phonePattern.test(value)) {
         setFieldState('phone', 'Enter a valid phone number, like 123-456-7890.');
         return false;
       }
       setFieldState('phone', '');
       return true;
     }

     fields.name.addEventListener('blur', validateName);
     fields.email.addEventListener('blur', validateEmail);
     fields.phone.addEventListener('blur', validatePhone);

     form.addEventListener('submit', (event) => {
       const valid = [validateName(), validateEmail(), validatePhone()].every(Boolean);
       if (!valid) {
         event.preventDefault();
         return;
       }

       event.preventDefault();
       form.reset();
       Object.keys(errorNodes).forEach((key) => setFieldState(key, ''));
     });
   </script>
 </body>
